## Building Error Chains

```xiom
pub type AppError = enum {
  Database(reason: DbError),
  Validation(reason: ValidationError),
  Network(reason: NetworkError),
}

fn get_user(id: Int) -> Result[User, AppError] {
  let conn = database::connect();
  match conn {
    Err(e) => return Err(AppError::Database(e)),  // Wrap low-level error
    Ok(c) => {
      let user = database::query(c, "SELECT * FROM users WHERE id = " + id.to_str());
      match user {
        Err(e) => return Err(AppError::Database(e)),
        Ok(u) => return Ok(u),
      }
    },
  }
}
```

### Adding Context at Each Layer

```xiom
fn handle_request(req: Request) -> Result[Response, AppError] {
  let user_id = parse_int(req.param("id"));
  match user_id {
    Err(e) => return Err(AppError::Validation(e)),
    Ok(id) => {
      let user = get_user(id);
      match user {
        Err(AppError::Database(e)) => {
          io.eprintln("DB error getting user " + id.to_str() + ": " + e.to_str());
          return Err(AppError::Database(e));
        },
        Err(e) => return Err(e),
        Ok(u) => return Ok(render_user(u)),
      }
    },
  }
}
```

### The `?` Operator for Propagation

```xiom
fn get_user(id: Int) -> Result[User, AppError] {
  let conn = database::connect()?;       // Propagates error, adds context
  let user = database::query(conn, sql)?; // Propagates error
  return Ok(user);
}
```

