pub type NetworkError = enum {
  Timeout(sec: Int),
  DnsFailure(host: Str),
}

pub type AppError = enum {
  Network(reason: NetworkError),
  Parse(reason: Str),
}

fn simulate_fetch() -> Result[Str, NetworkError] {
  return Err(NetworkError::Timeout(30));
}

fn fetch_data(url: Str) -> Result[Str, AppError] {
  let result = simulate_fetch();
  match result {
    Ok(data) => return Ok(data),
    Err(e) => return Err(AppError::Network(e)),
  }
}

fn main() -> Int {
  match fetch_data("https://example.com") {
    Ok(_) => return 1,
    Err(_) => return 0,
  }
}
